import java.util.Scanner;

public class Main {
    static final int N = 509;
    static int mod;
    static int[][] C = new int[N][N];
    static int[][] dp = new int[N][N];
    static int[][] dp2 = new int[N][N];
    static int[] f = new int[N];
    static int[] g = new int[N];

    static int add(int a, int b) {
        a += b;
        if (a >= mod) a -= mod;
        return a;
    }

    static int mul(int a, int b) {
        return (int) ((long) a * b % mod);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        mod = sc.nextInt();

        for (int i = 0; i <= n; i++) {
            C[i][0] = 1;
            for (int j = 0; j < i; j++) {
                C[i][j + 1] = add(C[i - 1][j + 1], C[i - 1][j]);
            }
        }

        f[0] = 1;
        g[0] = 0;
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= i + 1; j++) {
                f[i] = add(f[i], mul(mul(C[i - 1][j - 1], i + 1), f[j - 1] * f[i - j]));
                g[i] = add(g[i], mul(mul(C[i - 1][j - 1], i + 1),
                        add(mul(f[j - 1], g[i - j]), mul(g[j - 1], f[i - j]))));
                int temp = (j - 1) * j / 2 + (i - j + 1) * (i - j) / 2;
                g[i] = add(g[i], mul(mul(C[i - 1][j - 1], temp), mul(f[j - 1], f[i - j])));
            }
        }

        n += 1;
        dp[0][0] = 1;
        dp2[0][0] = 0;

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                for (int k = 0; j + k <= m && i + k + 1 <= n; k++) {
                    int val1 = mul(dp[i][j], f[k]);
                    int val2 = C[j + k][j];
                    dp[i + k + 1][j + k] = add(dp[i + k + 1][j + k], mul(val1, val2));

                    int val3 = mul(dp2[i][j], f[k]);
                    int val4 = mul(dp[i][j], g[k]);
                    dp2[i + k + 1][j + k] = add(dp2[i + k + 1][j + k], mul(val4 + val3, val2));
                }
            }
        }

        System.out.println(dp2[n][m]);
        sc.close();
    }
}

